API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(yarp_router, "YARP Router", ".NET / YARP on Azure Container Apps", "Forwards incoming HTTPS/JSON requests from the web application and routes internal requests via gRPC/mTLS.")
    Component(auth_middleware, "Authentication Middleware", ".NET Middleware", "Validates JWTs against Corporate Active Directory over HTTPS.")
}

Rel(yarp_router, auth_middleware, "Delegates token validation", "HTTPS")
Rel(auth_middleware, yarp_router, "Returns validation result", "")

@enduml
